referenceSolutions.javascript:
export function reverseBits(n        )         {
  let input = n >>> 0, result = 0; for (let bit = 0; bit < 32; bit++) { result = ((result << 1) | (input & 1)) >>> 0; input >>>= 1; } return result;
}

